    if (dom.docTitle && APP_CONFIG.meta && APP_CONFIG.meta.title) {
      dom.docTitle.textContent = APP_CONFIG.meta.title;
    }

    if (dom.navBrand) {
      dom.navBrand.textContent = navigation.brandLabel;
      dom.navBrand.setAttribute('aria-label', `返回${navigation.brandLabel}页面顶部`);
    }

    if (dom.navToggle) {
      dom.navToggle.setAttribute('aria-label', navigation.toggleOpenLabel);
    }

    if (dom.navLinksList) {
      dom.navLinksList.innerHTML = navigation.links
        .map((link) => `<li><a href="${escapeHtml(link.href)}">${escapeHtml(link.label)}</a></li>`)
        .join('');
    }

    if (dom.navActions) {
      dom.navActions.innerHTML = createButtonLinkMarkup('button-primary', navigation.cta);
    }
  };

  const renderHero = () => {
    const { hero } = APP_CONFIG;

    if (dom.heroEyebrow) dom.heroEyebrow.textContent = hero.eyebrow;
    if (dom.heroTitle) dom.heroTitle.textContent = hero.title;
    if (dom.heroDescription) dom.heroDescription.textContent = hero.description;
    if (dom.heroActions) {
      dom.heroActions.innerHTML = [
        createButtonLinkMarkup('button-primary', hero.primaryAction),
        createButtonLinkMarkup('button-secondary', hero.secondaryAction)
      ].join('');
    }
  };

  const renderFeatures = () => {
    const { features } = APP_CONFIG;

    if (dom.featuresEyebrow) dom.featuresEyebrow.textContent = features.eyebrow;
    if (dom.featuresTitle) dom.featuresTitle.textContent = features.title;
    if (dom.featuresDescription) dom.featuresDescription.textContent = features.description;

    if (!dom.featuresMount) return;

    dom.featuresMount.innerHTML = features.items
      .map((item) => `
        <article class="feature-card">
          <h3>${escapeHtml(item.title)}</h3>
          <p>${escapeHtml(item.description)}</p>
        </article>
      `)
      .join('');
  };

  const renderPricing = () => {
    const { pricing } = APP_CONFIG;
    const plans = normalizeRecommendedPlans(pricing.plans || []);

    if (dom.pricingEyebrow) dom.pricingEyebrow.textContent = pricing.eyebrow;
    if (dom.pricingTitle) dom.pricingTitle.textContent = pricing.title;
    if (dom.pricingDescription) dom.pricingDescription.textContent = pricing.description;

    if (!dom.pricingMount) return;

    dom.pricingMount.innerHTML = plans
      .map((plan) => {
        const display = getPricingDisplay(plan, state.billingPeriod);
        const featureItems = Array.isArray(plan.features)
          ? plan.features.map((feature) => `<li>${escapeHtml(feature)}</li>`).join('')
          : '';
        const recommendedBadge = plan.recommended ? '<span class="plan-badge">Recommended</span>' : '';
        const recommendedClass = plan.recommended ? ' is-recommended' : '';
        const periodText = display.period ? `<span class="plan-period">${escapeHtml(display.period)}</span>` : '';
        const valueTag = display.isFallback ? 'p' : 'p';

        return `
          <article class="pricing-card${recommendedClass}" ${plan.recommended ? 'data-recommended="true"' : ''}>
            <div class="pricing-card-header">
              ${recommendedBadge}
              <h3>${escapeHtml(plan.name)}</h3>
              <p>${escapeHtml(plan.description || '')}</p>
            </div>
            <div class="plan-price-wrap">
              <${valueTag} class="plan-price${display.isFallback ? ' is-fallback' : ''}">${escapeHtml(display.value)}</${valueTag}>
              <p class="plan-period-text">${periodText || `<span class="plan-period">${escapeHtml(display.period)}</span>`}</p>
            </div>
            <ul class="plan-features">
              ${featureItems}
            </ul>
            <div class="plan-actions">
              ${createButtonLinkMarkup(plan.recommended ? 'button-primary' : 'button-secondary', plan.cta)}
