          </article>
        `;
      })
      .join('');
  };

  const renderFaq = () => {
    const { faq } = APP_CONFIG;

    if (dom.faqEyebrow) dom.faqEyebrow.textContent = faq.eyebrow;
    if (dom.faqTitle) dom.faqTitle.textContent = faq.title;
    if (dom.faqDescription) dom.faqDescription.textContent = faq.description;

    if (!dom.faqMount) return;

    dom.faqMount.innerHTML = faq.items
      .map((item, index) => {
        const buttonId = `faq-trigger-${index + 1}`;
        const panelId = `faq-panel-${index + 1}`;

        return `
          <article class="faq-item">
            <h3 class="faq-question">
              <button
                id="${buttonId}"
                class="faq-toggle"
                type="button"
                aria-expanded="false"
                aria-controls="${panelId}"
              >
                <span>${escapeHtml(item.question)}</span>
              </button>
            </h3>
            <div
              id="${panelId}"
              class="faq-answer"
              role="region"
              aria-labelledby="${buttonId}"
              hidden
            >
              <p>${escapeHtml(item.answer)}</p>
            </div>
          </article>
        `;
      })
      .join('');
  };

  const renderFinalCta = () => {
    const { finalCta } = APP_CONFIG;

    if (dom.finalCtaEyebrow) dom.finalCtaEyebrow.textContent = finalCta.eyebrow;
    if (dom.finalCtaTitle) dom.finalCtaTitle.textContent = finalCta.title;
    if (dom.finalCtaDescription) dom.finalCtaDescription.textContent = finalCta.description;
    if (dom.finalCtaActions) {
      dom.finalCtaActions.innerHTML = [
        createButtonLinkMarkup('button-primary', finalCta.primaryAction),
        createButtonLinkMarkup('button-secondary', finalCta.secondaryAction)
      ].join('');
    }
  };

  const renderFooter = () => {
    const currentYear = new Date().getFullYear();

    if (dom.footerMeta) {
      dom.footerMeta.textContent = `© ${currentYear} ${APP_CONFIG.productName}。保留所有权利。`;
    }

    if (dom.footerLinks) {
      dom.footerLinks.innerHTML = APP_CONFIG.footer.links
        .map((link) => `<a href="${escapeHtml(link.href)}" aria-label="${escapeHtml(link.ariaLabel || link.label)}">${escapeHtml(link.label)}</a>`)
        .join('');
    }
  };

  const updatePricingToggleUI = () => {
    if (!dom.toggleButtons.length) return;

    dom.toggleButtons.forEach((button, index) => {
      const period = index === 0 ? 'monthly' : 'yearly';
      const isActive = state.billingPeriod === period;
      button.textContent = APP_CONFIG.pricing.toggleLabels[period] || button.textContent;
      button.classList.toggle('is-active', isActive);
      button.setAttribute('aria-pressed', String(isActive));
      button.dataset.billing = period;
    });
  };

  const setBillingPeriod = (period) => {
    if (!['monthly', 'yearly'].includes(period)) {
      return;
    }

    state.billingPeriod = period;
    updatePricingToggleUI();
    renderPricing();
  };

  const closeMenu = () => {
    if (!dom.navMenu || !dom.navToggle) return;
    dom.navMenu.classList.remove('is-open');
    dom.navToggle.setAttribute('aria-expanded', 'false');
    dom.navToggle.setAttribute('aria-label', APP_CONFIG.navigation.toggleOpenLabel);
  };

  const openMenu = () => {
    if (!dom.navMenu || !dom.navToggle) return;
    dom.navMenu.classList.add('is-open');
    dom.navToggle.setAttribute('aria-expanded', 'true');
    dom.navToggle.setAttribute('aria-label', APP_CONFIG.navigation.toggleCloseLabel);
  };

  const toggleMenu = () => {
    if (!dom.navMenu) return;
    const isOpen = dom.navMenu.classList.contains('is-open');
    if (isOpen) {
      closeMenu();
    } else {
      openMenu();
    }
  };

  const smoothScrollToHash = (hash) => {
    if (!hash || hash === '#') return;

    const target = document.querySelector(hash);
    if (!target) return;

    const navOffset = dom.navToggle && window.getComputedStyle(document.documentElement)
      ? parseFloat(window.getComputedStyle(document.documentElement).getPropertyValue('--nav-height')) || 72
      : 72;
    const extraOffset = 16;
    const top = target.getBoundingClientRect().top + window.scrollY - navOffset - extraOffset;

    window.scrollTo({
      top: Math.max(top, 0),
      behavior: 'smooth'
    });

    window.setTimeout(() => {
      if (!target.hasAttribute('tabindex')) {
        target.setAttribute('tabindex', '-1');
      }
      target.focus({ preventScroll: true });
    }, 300);
  };

  const handleFaqToggle = (button) => {
    const controls = button.getAttribute('aria-controls');
    if (!controls) return;

    const panel = document.getElementById(controls);
    if (!panel) return;

    const expanded = button.getAttribute('aria-expanded') === 'true';
    button.setAttribute('aria-expanded', String(!expanded));
    panel.hidden = expanded;
  };

  const bindEvents = () => {
    if (dom.navToggle) {
      dom.navToggle.addEventListener('click', toggleMenu);
    }

    if (dom.navMenu) {
      dom.navMenu.addEventListener('click', (event) => {
        const link = event.target.closest('a[href^="#"]');
        if (link) {
          closeMenu();
        }
      });
    }

    if (dom.pricingToggle) {
      dom.pricingToggle.addEventListener('click', (event) => {
        const button = event.target.closest('.toggle-option');
        if (!button) return;
        const billing = button.dataset.billing || (dom.toggleButtons.indexOf(button) === 0 ? 'monthly' : 'yearly');
        setBillingPeriod(billing);
      });
    }

    if (dom.faqMount) {
      dom.faqMount.addEventListener('click', (event) => {
        const button = event.target.closest('.faq-toggle');
        if (!button) return;
        handleFaqToggle(button);
      });
    }

    document.addEventListener('click', (event) => {
      const anchor = event.target.closest('a[href^="#"]');
      if (!anchor) return;

      const href = anchor.getAttribute('href');
      if (!href || href === '#') return;

      const target = document.querySelector(href);
      if (!target) return;

      event.preventDefault();
      smoothScrollToHash(href);
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') {
        closeMenu();
      }
    });
  };

  const renderApp = () => {
    renderNavigation();
    renderHero();
    renderFeatures();
    updatePricingToggleUI();
    renderPricing();
    renderFaq();
    renderFinalCta();
    renderFooter();
  };

  const init = () => {
    try {
      cacheDom();
      renderApp();
      bindEvents();
    } catch (error) {
      console.error('App initialization failed:', error);
    }
  };

  document.addEventListener('DOMContentLoaded', init);
})();

