    if (dom.pricingMount) {
      dom.pricingMount.innerHTML = normalizedPlans.map((plan, index) => createPricingCardMarkup(plan, index)).join('');
    }

    updatePricingToggleUI();
  };

  const updatePricingToggleUI = () => {
    if (!dom.toggleButtons || !dom.toggleButtons.length) {
      return;
    }

    dom.toggleButtons.forEach((button) => {
      const isActive = button.dataset.period === state.billingPeriod;
      button.classList.toggle('is-active', isActive);
