    dom.navToggle.setAttribute('aria-expanded', 'false');
    dom.navToggle.setAttribute('aria-label', APP_CONFIG.navigation.toggleOpenLabel);
  };

  const openMobileMenu = () => {
    if (!dom.navMenu || !dom.navToggle) {
      return;
    }

    dom.navMenu.classList.add('is-open');
    dom.navToggle.setAttribute('aria-expanded', 'true');
    dom.navToggle.setAttribute('aria-label', APP_CONFIG.navigation.toggleCloseLabel);
  };

  const toggleMobileMenu = () => {
    if (!dom.navMenu) {
      return;
    }

    if (dom.navMenu.classList.contains('is-open')) {
      closeMobileMenu();
    } else {
      openMobileMenu();
    }
  };

  const updatePricingCards = () => {
    renderPricing();
  };

  const smoothScrollToHash = (hash) => {
    if (!hash || hash === '#') {
      return;
    }

    const target = document.querySelector(hash);
    if (!target) {
      return;
    }

    const focusTarget = target.matches('h1, h2, h3, h4, h5, h6, section, main, header, footer, article')
      ? target
      : target.closest('section, main, article') || target;

    target.scrollIntoView({
      behavior: 'smooth',
      block: 'start'
    });

    window.setTimeout(() => {
      if (!focusTarget.hasAttribute('tabindex')) {
        focusTarget.setAttribute('tabindex', '-1');
      }
      focusTarget.focus({ preventScroll: true });
    }, 320);
  };

  const handleFaqToggle = (trigger) => {
    if (!trigger) {
      return;
    }

    const panelId = trigger.getAttribute('aria-controls');
    const panel = panelId ? document.getElementById(panelId) : null;
    if (!panel) {
      return;
    }

    const expanded = trigger.getAttribute('aria-expanded') === 'true';
    trigger.setAttribute('aria-expanded', String(!expanded));
    panel.hidden = expanded;
  };

  const bindEvents = () => {
    if (dom.navToggle) {
      dom.navToggle.addEventListener('click', () => {
        toggleMobileMenu();
      });
    }

    document.addEventListener('click', (event) => {
      const target = event.target;
      if (!(target instanceof Element)) {
        return;
      }

      const faqTrigger = target.closest('.faq-trigger');
      if (faqTrigger) {
        handleFaqToggle(faqTrigger);
        return;
      }

      const toggleButton = target.closest('.toggle-option');
      if (toggleButton && toggleButton.dataset.period) {
        state.billingPeriod = toggleButton.dataset.period === 'yearly' ? 'yearly' : 'monthly';
        updatePricingCards();
        return;
      }

      const anchor = target.closest('a[href^="#"]');
      if (anchor) {
        const href = anchor.getAttribute('href') || '';
        if (href !== '#' && document.querySelector(href)) {
          event.preventDefault();
          if (dom.navMenu && anchor.closest('.nav-menu')) {
            closeMobileMenu();
          }
          smoothScrollToHash(href);
          if (window.history && typeof window.history.pushState === 'function') {
            window.history.pushState(null, '', href);
          }
        }
      }
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') {
        closeMobileMenu();
      }
    });

    window.addEventListener('resize', () => {
      if (window.innerWidth >= 768) {
        closeMobileMenu();
      }
    });
  };

  const init = () => {
    cacheDom();
    renderNavigation();
    renderHero();
    renderFeatures();
    renderPricing();
    renderFaq();
    renderFinalCta();
    renderFooter();
    bindEvents();
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init, { once: true });
  } else {
    init();
  }
})();

