      const isActive = button.dataset.period === currentPeriod;
      button.classList.toggle('is-active', isActive);
      button.setAttribute('aria-pressed', String(isActive));
    });
  };

  const setMenuOpen = (isOpen) => {
    if (!dom.navMenu || !dom.navToggle) {
      return;
    }

    dom.navMenu.classList.toggle('is-open', isOpen);
    dom.navToggle.setAttribute('aria-expanded', String(isOpen));
    dom.navToggle.setAttribute(
      'aria-label',
      isOpen ? APP_CONFIG.navigation.toggleCloseLabel : APP_CONFIG.navigation.toggleOpenLabel
    );
  };

  const closeMenu = () => setMenuOpen(false);

  const getHeaderOffset = () => {
    if (!dom.siteHeader) {
      return 88;
    }

    return Math.ceil(dom.siteHeader.getBoundingClientRect().height) + 16;
  };

  const focusTargetHeading = (section) => {
    if (!section) {
      return;
    }

    const heading = section.querySelector('h1, h2, h3');
    const target = heading || section;

    if (!target.hasAttribute('tabindex')) {
      target.setAttribute('tabindex', '-1');
    }

    window.setTimeout(() => {
      target.focus({ preventScroll: true });
    }, 220);
  };

  const scrollToHash = (hash) => {
    if (!hash || hash === '#') {
      return;
    }

    const target = document.querySelector(hash);
    if (!target) {
      return;
    }

    const y = window.scrollY + target.getBoundingClientRect().top - getHeaderOffset();
    window.scrollTo({ top: Math.max(y, 0), behavior: 'smooth' });
    focusTargetHeading(target);

    if (window.history && typeof window.history.pushState === 'function') {
      window.history.pushState(null, '', hash);
    }
  };

  const handlePricingToggleClick = (event) => {
    const button = event.target.closest('.toggle-option');
    if (!button || !button.dataset.period) {
      return;
    }

    const nextPeriod = button.dataset.period;
    if (nextPeriod !== 'monthly' && nextPeriod !== 'yearly') {
      return;
    }

    if (state.billingPeriod === nextPeriod) {
      syncPricingToggleUi();
      return;
    }

    state.billingPeriod = nextPeriod;
    renderPricing();
  };

  const handleFaqToggleClick = (event) => {
    const trigger = event.target.closest('.faq-trigger');
    if (!trigger) {
      return;
    }

    const panelId = trigger.getAttribute('aria-controls');
    if (!panelId) {
      return;
    }

    const panel = document.getElementById(panelId);
    if (!panel) {
      return;
    }

    const expanded = trigger.getAttribute('aria-expanded') === 'true';
    trigger.setAttribute('aria-expanded', String(!expanded));
    panel.hidden = expanded;
  };

  const handleGlobalAnchorClick = (event) => {
    const anchor = event.target.closest('a[href^="#"]');
    if (!anchor) {
      return;
    }

    const href = anchor.getAttribute('href');
    if (!href || href === '#') {
      return;
    }

    const target = document.querySelector(href);
    if (!target) {
      return;
    }

    event.preventDefault();
    closeMenu();
    scrollToHash(href);
  };

  const bindEvents = () => {
    if (dom.navToggle) {
      dom.navToggle.addEventListener('click', () => {
        const isExpanded = dom.navToggle.getAttribute('aria-expanded') === 'true';
        setMenuOpen(!isExpanded);
      });
    }

    if (dom.pricingToggle) {
      dom.pricingToggle.addEventListener('click', handlePricingToggleClick);
    }

    if (dom.faqMount) {
      dom.faqMount.addEventListener('click', handleFaqToggleClick);
    }

    document.addEventListener('click', handleGlobalAnchorClick);

    document.addEventListener('click', (event) => {
      if (!dom.navMenu || !dom.navToggle) {
        return;
      }

      const isOpen = dom.navMenu.classList.contains('is-open');
      if (!isOpen) {
        return;
      }

      const clickedInsideMenu = event.target.closest('.nav-menu, .nav-toggle');
      if (!clickedInsideMenu) {
        closeMenu();
      }
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') {
        closeMenu();
      }
    });
  };

  const init = () => {
    cacheDom();
    renderNavigation();
    renderHero();
    renderFeatures();
    renderPricing();
    renderFaq();
    renderFinalCta();
    renderFooter();
    bindEvents();
    closeMenu();
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init, { once: true });
  } else {
    init();
  }
})();

