    if (!dom.navMenu) {
      return;
    }

    if (dom.navMenu.classList.contains('is-open')) {
      closeMobileMenu();
    } else {
      openMobileMenu();
    }
  };

  const focusTargetHeading = (target) => {
    if (!(target instanceof HTMLElement)) {
      return;
    }

    const heading = target.matches('h1, h2, h3, h4, h5, h6')
      ? target
      : target.querySelector('h1, h2, h3, h4, h5, h6');

    const focusable = heading || target;
    focusable.setAttribute('tabindex', '-1');
    focusable.focus({ preventScroll: true });
    window.setTimeout(() => {
      if (focusable.getAttribute('tabindex') === '-1') {
        focusable.removeAttribute('tabindex');
      }
    }, 500);
  };

  const scrollToHashTarget = (hash) => {
    if (!hash || hash === '#') {
      return;
    }

    const target = document.querySelector(hash);

    if (!target) {
      return;
    }

    const headerOffset = dom.siteHeader ? dom.siteHeader.offsetHeight : 0;
    const extraOffset = 16;
    const targetTop = target.getBoundingClientRect().top + window.scrollY - headerOffset - extraOffset;

    window.scrollTo({
      top: Math.max(targetTop, 0),
      behavior: 'smooth'
    });

    focusTargetHeading(target);
  };

  const handleAnchorClick = (event) => {
    const link = event.target instanceof Element ? event.target.closest('a[href^="#"]') : null;

    if (!link) {
      return;
    }

    const href = link.getAttribute('href');

    if (!href || href === '#') {
      return;
    }

    const target = document.querySelector(href);

    if (!target) {
      return;
    }

    event.preventDefault();
    scrollToHashTarget(href);

    if (dom.navMenu && dom.navMenu.contains(link)) {
      closeMobileMenu();
    }

    if (window.history && typeof window.history.pushState === 'function') {
      window.history.pushState(null, '', href);
    }
  };

  const bindPricingToggle = () => {
    dom.pricingToggleButtons.forEach((button, index) => {
      button.addEventListener('click', () => {
        const nextPeriod = index === 0 ? 'monthly' : 'yearly';

        if (state.billingPeriod === nextPeriod) {
          return;
        }

        state.billingPeriod = nextPeriod;
        updatePricingToggleUi();
        updatePricingCards();
      });
    });
  };

  const bindFaq = () => {
    if (!dom.faqMount) {
      return;
    }

    dom.faqMount.addEventListener('click', (event) => {
      const button = event.target instanceof Element ? event.target.closest('.faq-question') : null;

      if (!button) {
        return;
      }

      const controlsId = button.getAttribute('aria-controls');
      const panel = controlsId ? document.getElementById(controlsId) : null;
      const expanded = button.getAttribute('aria-expanded') === 'true';
      const nextExpanded = !expanded;

      button.setAttribute('aria-expanded', String(nextExpanded));

      if (panel) {
        panel.hidden = !nextExpanded;
      }
    });
  };

  const bindMobileMenu = () => {
    if (dom.navToggle) {
      dom.navToggle.addEventListener('click', toggleMobileMenu);
    }

    document.addEventListener('click', (event) => {
      if (!dom.navMenu || !dom.navToggle) {
        return;
      }

      const target = event.target;
      const clickedInsideMenu = target instanceof Node && dom.navMenu.contains(target);
      const clickedToggle = target instanceof Node && dom.navToggle.contains(target);

      if (!clickedInsideMenu && !clickedToggle && dom.navMenu.classList.contains('is-open')) {
        closeMobileMenu();
      }
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && dom.navMenu && dom.navMenu.classList.contains('is-open')) {
        closeMobileMenu();
        if (dom.navToggle) {
          dom.navToggle.focus();
        }
      }
    });

    window.addEventListener('resize', () => {
      if (window.innerWidth >= 768) {
        closeMobileMenu();
      }
    });
  };

  const bindAnchors = () => {
    document.addEventListener('click', handleAnchorClick);
  };

  const initializeDocumentMeta = () => {
    document.title = `产品着陆页 | ${APP_CONFIG.productName}`;

    const description = document.querySelector('meta[name="description"]');
