      );
    }

    const ogTitle = document.querySelector('meta[property="og:title"]');
    if (ogTitle) {
      ogTitle.setAttribute('content', `产品着陆页 | ${APP_CONFIG.productName}`);
    }

    const ogDescription = document.querySelector('meta[property="og:description"]');
    if (ogDescription) {
      ogDescription.setAttribute(
        'content',
        `探索 ${APP_CONFIG.productName} 的功能、价格与常见问题，立即开始体验更高效的工作方式。`
      );
    }
  };

  const initialize = () => {
    cacheDom();
    initializeDocumentMeta();
    renderNavigation();
    renderHero();
    renderFeatures();
    renderPricing();
    updatePricingToggleUi();
    renderFaq();
    renderFinalCta();
    renderFooter();
    closeMobileMenu();
    bindPricingToggle();
    bindFaq();
    bindMobileMenu();
    bindAnchors();
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initialize, { once: true });
  } else {
    initialize();
  }
})();

