    if (!(trigger instanceof HTMLButtonElement)) {
      return;
    }

    const controlsId = trigger.getAttribute('aria-controls');
    const panel = controlsId ? document.getElementById(controlsId) : null;

    if (!panel) {
      return;
    }

    const expanded = trigger.getAttribute('aria-expanded') === 'true';
    const nextExpanded = !expanded;

    setAttribute(trigger, 'aria-expanded', String(nextExpanded));
    panel.hidden = !nextExpanded;
  };

  const getHeaderOffset = () => {
    return dom.siteHeader ? dom.siteHeader.getBoundingClientRect().height : 0;
  };

  const smoothScrollToHash = (hash, options = {}) => {
    if (!hash || hash === '#') {
      return;
    }

    const target = document.querySelector(hash);
    if (!target) {
      return;
    }

    const headerOffset = getHeaderOffset() + 16;
    const targetTop = window.scrollY + target.getBoundingClientRect().top - headerOffset;
    window.scrollTo({
      top: Math.max(targetTop, 0),
      behavior: 'smooth'
    });

    if (options.updateHistory !== false && window.history && typeof window.history.pushState === 'function') {
      window.history.pushState(null, '', hash);
    }

    window.setTimeout(() => {
      if (!target.hasAttribute('tabindex')) {
        target.setAttribute('tabindex', '-1');
      }
      target.focus({ preventScroll: true });
    }, 300);
  };

  const handleDocumentClick = (event) => {
    const target = event.target;
    if (!(target instanceof Element)) {
      return;
    }

    const navToggleClicked = target.closest('.nav-toggle');
    if (navToggleClicked) {
      setMenuOpen(!state.isMenuOpen);
      return;
    }

    const navLink = target.closest('.nav-links a, .nav-actions a');
    if (navLink instanceof HTMLAnchorElement) {
      if (state.isMenuOpen) {
        setMenuOpen(false);
      }
    }

    const faqTrigger = target.closest('.faq-trigger');
    if (faqTrigger instanceof HTMLButtonElement) {
      toggleFaqItem(faqTrigger);
      return;
    }

    const anchor = target.closest('a[href^="#"]');
    if (anchor instanceof HTMLAnchorElement) {
      const href = anchor.getAttribute('href') || '';
      if (href.length > 1) {
        event.preventDefault();
        smoothScrollToHash(href);
      }
    }
  };

  const handlePricingToggleClick = (event) => {
    const target = event.target;
    if (!(target instanceof Element)) {
      return;
    }

    const toggleButton = target.closest('.toggle-option');
    if (!(toggleButton instanceof HTMLButtonElement)) {
      return;
    }

    setBillingPeriod(toggleButton.dataset.period || 'monthly');
  };

