  color: var(--color-primary);
  font-size: var(--font-size-sm);
  font-weight: 700;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1,
h2,
h3 {
  color: var(--color-text);
  line-height: var(--line-height-tight);
  letter-spacing: -0.03em;
}

h1 {
  margin-bottom: var(--space-5);
  font-size: var(--font-size-2xl);
}

h2 {
