    opacity: 1;
    visibility: visible;
    transform: none;
    pointer-events: auto;
  }

  .nav-links {
    display: flex;
    align-items: center;
    gap: var(--space-2);
  }

  .nav-actions {
    width: auto;
  }

  .nav-actions .button {
    width: auto;
  }

  .hero {
    grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
  }

  .features-mount {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .pricing-mount {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    align-items: stretch;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }

  .button:hover,
  .toggle-option:hover,
  .nav-toggle:hover,
  .nav-links a:hover,
  .footer-links a:hover,
  .pricing-mount > .is-featured,
  .pricing-mount > [data-featured="true"],
  .pricing-mount > [aria-current="true"] {
    transform: none;
  }
}

