      title: '立即为你的团队开启更高效的下一步',
      description: '立即体验更顺滑的流程管理、更清晰的协作视图与更稳定的增长节奏。',
      primaryAction: {
        label: '立即开始',
        href: '#top',
        ariaLabel: '立即开始并返回顶部'
      },
      secondaryAction: {
        label: '了解更多',
        href: '#faq',
        ariaLabel: '先查看常见问题'
      }
    },
    footer: {
      links: [
        { label: '隐私政策', href: '#', ariaLabel: '查看隐私政策' },
        { label: '服务条款', href: '#', ariaLabel: '查看服务条款' },
        { label: '联系支持', href: '#', ariaLabel: '联系支持团队' }
      ]
    }
  };

  const state = {
    billingPeriod: 'monthly',
    isMenuOpen: false
  };

  const dom = {};

  const escapeHtml = (value) => String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

  const setText = (element, value) => {
    if (element) {
      element.textContent = value;
    }
  };

  const setHtml = (element, value) => {
    if (element) {
      element.innerHTML = value;
    }
  };

  const setAttribute = (element, name, value) => {
    if (element) {
      element.setAttribute(name, value);
    }
  };

  const createButtonLinkMarkup = (buttonClass, action) => {
    if (!action || !action.label || !action.href) {
      return '';
    }

    const aria = action.ariaLabel ? ` aria-label="${escapeHtml(action.ariaLabel)}"` : '';
    return `<a class="button ${escapeHtml(buttonClass)}" href="${escapeHtml(action.href)}"${aria}>${escapeHtml(action.label)}</a>`;
  };

  const normalizeRecommendedPlans = (plans) => {
    let recommendedUsed = false;

    return (Array.isArray(plans) ? plans : []).map((plan) => {
      const nextPlan = { ...plan };

      if (nextPlan.recommended && !recommendedUsed) {
        recommendedUsed = true;
        nextPlan.recommended = true;
      } else {
        nextPlan.recommended = false;
      }

      return nextPlan;
    });
  };

  const getSafePlans = () => normalizeRecommendedPlans(APP_CONFIG.pricing && APP_CONFIG.pricing.plans ? APP_CONFIG.pricing.plans : []);

  const formatPrice = (value) => {
    if (typeof value !== 'number' || Number.isNaN(value)) {
      return APP_CONFIG.pricing.fallbackText;
    }

    return new Intl.NumberFormat('zh-CN', {
      style: 'currency',
      currency: 'CNY',
      maximumFractionDigits: 0
    }).format(value);
  };

  const getPricingDisplay = (plan, billingPeriod) => {
    const prices = plan && typeof plan === 'object' && plan.prices ? plan.prices : {};
    const rawPrice = prices[billingPeriod];

    if (typeof rawPrice !== 'number' || Number.isNaN(rawPrice)) {
      return {
        value: APP_CONFIG.pricing.fallbackText,
        period: APP_CONFIG.pricing.fallbackPeriodText,
        isFallback: true
      };
    }

    return {
      value: formatPrice(rawPrice),
      period: APP_CONFIG.pricing.periods[billingPeriod] || '',
      isFallback: false
    };
  };

  const cacheDom = () => {
    dom.siteHeader = document.querySelector('.site-header');
    dom.navBrand = document.querySelector('.nav-brand a');
    dom.navToggle = document.querySelector('.nav-toggle');
    dom.navMenu = document.querySelector('.nav-menu');
    dom.navLinksList = document.querySelector('.nav-links');
    dom.navActions = document.querySelector('.nav-actions');

    dom.heroSection = document.getElementById('hero');
    dom.heroEyebrow = document.querySelector('.hero .eyebrow');
    dom.heroTitle = document.getElementById('hero-title');
    dom.heroDescription = document.querySelector('.hero-description');
    dom.heroActions = document.querySelector('.hero-actions');

    dom.featuresSection = document.getElementById('features');
    dom.featuresHeading = dom.featuresSection ? dom.featuresSection.querySelector('.section-heading') : null;
    dom.featuresEyebrow = dom.featuresHeading ? dom.featuresHeading.querySelector('.eyebrow') : null;
    dom.featuresTitle = document.getElementById('features-title');
    dom.featuresDescription = dom.featuresHeading ? dom.featuresHeading.querySelectorAll('p')[1] || null : null;
    dom.featuresMount = document.querySelector('.features-mount');

    dom.pricingSection = document.getElementById('pricing');
    dom.pricingHeading = dom.pricingSection ? dom.pricingSection.querySelector('.section-heading') : null;
    dom.pricingEyebrow = dom.pricingHeading ? dom.pricingHeading.querySelector('.eyebrow') : null;
    dom.pricingTitle = document.getElementById('pricing-title');
    dom.pricingDescription = dom.pricingHeading ? dom.pricingHeading.querySelectorAll('p')[1] || null : null;
    dom.pricingToggle = document.querySelector('.pricing-toggle');
    dom.pricingToggleButtons = dom.pricingToggle ? Array.from(dom.pricingToggle.querySelectorAll('.toggle-option')) : [];
    dom.pricingMount = document.querySelector('.pricing-mount');

    dom.faqSection = document.getElementById('faq');
    dom.faqHeading = dom.faqSection ? dom.faqSection.querySelector('.section-heading') : null;
    dom.faqEyebrow = dom.faqHeading ? dom.faqHeading.querySelector('.eyebrow') : null;
    dom.faqTitle = document.getElementById('faq-title');
    dom.faqDescription = dom.faqHeading ? dom.faqHeading.querySelectorAll('p')[1] || null : null;
    dom.faqMount = document.querySelector('.faq-mount');

    dom.finalCtaSection = document.getElementById('final-cta');
    dom.finalCtaContent = dom.finalCtaSection ? dom.finalCtaSection.querySelector('.final-cta-content') : null;
    dom.finalCtaEyebrow = dom.finalCtaContent ? dom.finalCtaContent.querySelector('.eyebrow') : null;
    dom.finalCtaTitle = document.getElementById('final-cta-title');
    dom.finalCtaDescription = dom.finalCtaContent ? dom.finalCtaContent.querySelectorAll('p')[1] || null : null;
    dom.finalCtaActions = dom.finalCtaContent ? dom.finalCtaContent.querySelector('.final-cta-actions') : null;

    dom.footerMeta = document.querySelector('.footer-meta p');
    dom.footerLinks = document.querySelector('.footer-links');
  };

  const renderNavigation = () => {
    setText(dom.navBrand, APP_CONFIG.navigation.brandLabel || APP_CONFIG.productName);
    setAttribute(dom.navBrand, 'aria-label', `返回 ${APP_CONFIG.productName} 页面顶部`);

    if (dom.navLinksList) {
      const linksMarkup = (APP_CONFIG.navigation.links || []).map((link) => (
        `<li><a href="${escapeHtml(link.href)}">${escapeHtml(link.label)}</a></li>`
      )).join('');
      setHtml(dom.navLinksList, linksMarkup);
    }

    if (dom.navActions) {
      setHtml(dom.navActions, createButtonLinkMarkup('button-primary', APP_CONFIG.navigation.cta));
    }

    if (dom.navToggle) {
      setAttribute(dom.navToggle, 'aria-label', APP_CONFIG.navigation.toggleOpenLabel);
      setAttribute(dom.navToggle, 'aria-expanded', 'false');
    }
  };

  const renderHero = () => {
    setText(dom.heroEyebrow, APP_CONFIG.hero.eyebrow);
    setText(dom.heroTitle, APP_CONFIG.hero.title);
    setText(dom.heroDescription, APP_CONFIG.hero.description);

    if (dom.heroActions) {
      setHtml(
        dom.heroActions,
        `${createButtonLinkMarkup('button-primary', APP_CONFIG.hero.primaryAction)}${createButtonLinkMarkup('button-secondary', APP_CONFIG.hero.secondaryAction)}`
      );
    }
  };

  const renderFeatures = () => {
    setText(dom.featuresEyebrow, APP_CONFIG.features.eyebrow);
    setText(dom.featuresTitle, APP_CONFIG.features.title);
    setText(dom.featuresDescription, APP_CONFIG.features.description);

    if (dom.featuresMount) {
      const markup = (APP_CONFIG.features.items || []).map((item) => `
        <article class="feature-card">
          <h3>${escapeHtml(item.title)}</h3>
          <p>${escapeHtml(item.description)}</p>
        </article>
      `).join('');

      setHtml(dom.featuresMount, markup);
    }
  };

  const renderPricing = () => {
    setText(dom.pricingEyebrow, APP_CONFIG.pricing.eyebrow);
    setText(dom.pricingTitle, APP_CONFIG.pricing.title);
    setText(dom.pricingDescription, APP_CONFIG.pricing.description);

    if (dom.pricingToggleButtons.length >= 2) {
      dom.pricingToggleButtons[0].textContent = APP_CONFIG.pricing.toggleLabels.monthly;
      dom.pricingToggleButtons[1].textContent = APP_CONFIG.pricing.toggleLabels.yearly;
    }

    const plans = getSafePlans();

    if (dom.pricingMount) {
      const markup = plans.map((plan) => {
        const priceDisplay = getPricingDisplay(plan, state.billingPeriod);
        const featuresMarkup = (Array.isArray(plan.features) ? plan.features : []).map((feature) => (
          `<li>${escapeHtml(feature)}</li>`
        )).join('');
        const badgeMarkup = plan.recommended
          ? `<p class="plan-badge">${escapeHtml(APP_CONFIG.pricing.recommendedBadge)}</p>`
          : '';

        return `
          <article class="pricing-card${plan.recommended ? ' is-recommended' : ''}">
            ${badgeMarkup}
            <h3>${escapeHtml(plan.name || '')}</h3>
            <p>${escapeHtml(plan.description || '')}</p>
            <div class="plan-price-wrap">
              <p class="plan-price">${escapeHtml(priceDisplay.value)}</p>
              <p class="plan-period">${escapeHtml(priceDisplay.period)}</p>
            </div>
            <ul class="plan-features">
              ${featuresMarkup}
            </ul>
            ${createButtonLinkMarkup(plan.recommended ? 'button-primary' : 'button-secondary', plan.cta)}
          </article>
        `;
      }).join('');

      setHtml(dom.pricingMount, markup);
    }

    updatePricingToggleUi();
  };

  const updatePricingToggleUi = () => {
    dom.pricingToggleButtons.forEach((button, index) => {
      const period = index === 0 ? 'monthly' : 'yearly';
      const isActive = state.billingPeriod === period;
      button.classList.toggle('is-active', isActive);
      button.setAttribute('aria-pressed', String(isActive));
    });
  };

  const renderFaq = () => {
    setText(dom.faqEyebrow, APP_CONFIG.faq.eyebrow);
    setText(dom.faqTitle, APP_CONFIG.faq.title);
    setText(dom.faqDescription, APP_CONFIG.faq.description);

    if (dom.faqMount) {
      const markup = (APP_CONFIG.faq.items || []).map((item, index) => {
        const panelId = `faq-panel-${index + 1}`;
        const buttonId = `faq-button-${index + 1}`;

        return `
          <article class="faq-item">
            <h3>
              <button
                id="${panelId ? escapeHtml(buttonId) : ''}"
                class="faq-question"
                type="button"
                aria-expanded="false"
                aria-controls="${escapeHtml(panelId)}"
              >
                <span>${escapeHtml(item.question)}</span>
              </button>
            </h3>
            <div
              id="${escapeHtml(panelId)}"
              class="faq-answer"
              role="region"
              aria-labelledby="${escapeHtml(buttonId)}"
              hidden
            >
              <p>${escapeHtml(item.answer)}</p>
            </div>
          </article>
        `;
      }).join('');

      setHtml(dom.faqMount, markup);
    }
  };

  const renderFinalCta = () => {
    setText(dom.finalCtaEyebrow, APP_CONFIG.finalCta.eyebrow);
    setText(dom.finalCtaTitle, APP_CONFIG.finalCta.title);
    setText(dom.finalCtaDescription, APP_CONFIG.finalCta.description);

    if (dom.finalCtaActions) {
      setHtml(
        dom.finalCtaActions,
        `${createButtonLinkMarkup('button-primary', APP_CONFIG.finalCta.primaryAction)}${createButtonLinkMarkup('button-secondary', APP_CONFIG.finalCta.secondaryAction)}`
      );
    }
  };

  const renderFooter = () => {
    const year = new Date().getFullYear();
    setText(dom.footerMeta, `© ${year} ${APP_CONFIG.productName}。保留所有权利。`);

    if (dom.footerLinks) {
      const markup = (APP_CONFIG.footer.links || []).map((link) => {
        const aria = link.ariaLabel ? ` aria-label="${escapeHtml(link.ariaLabel)}"` : '';
        return `<a href="${escapeHtml(link.href)}"${aria}>${escapeHtml(link.label)}</a>`;
      }).join('');

      setHtml(dom.footerLinks, markup);
    }
  };

  const setMenuOpen = (isOpen) => {
    state.isMenuOpen = Boolean(isOpen);

    if (dom.navMenu) {
      dom.navMenu.classList.toggle('is-open', state.isMenuOpen);
    }

    if (dom.navToggle) {
      dom.navToggle.setAttribute('aria-expanded', String(state.isMenuOpen));
      dom.navToggle.setAttribute(
        'aria-label',
        state.isMenuOpen ? APP_CONFIG.navigation.toggleCloseLabel : APP_CONFIG.navigation.toggleOpenLabel
      );
    }
  };

  const handlePricingToggle = (event) => {
    const button = event.target.closest('.toggle-option');
    if (!button || !dom.pricingToggle || !dom.pricingToggle.contains(button)) {
      return;
    }

    const nextPeriod = dom.pricingToggleButtons.indexOf(button) === 1 ? 'yearly' : 'monthly';
    if (state.billingPeriod === nextPeriod) {
      return;
    }

    state.billingPeriod = nextPeriod;
    renderPricing();
  };

  const handleFaqToggle = (event) => {
    const button = event.target.closest('.faq-question');
    if (!button) {
      return;
    }

    const panelId = button.getAttribute('aria-controls');
    if (!panelId) {
      return;
    }

    const panel = document.getElementById(panelId);
    if (!panel) {
      return;
    }

    const expanded = button.getAttribute('aria-expanded') === 'true';
    button.setAttribute('aria-expanded', String(!expanded));
    panel.hidden = expanded;
  };

  const getHeaderOffset = () => {
    return dom.siteHeader ? dom.siteHeader.getBoundingClientRect().height : 0;
  };

  const smoothScrollToHash = (hash, shouldFocus) => {
    if (!hash || hash.charAt(0) !== '#') {
      return;
    }

    const target = document.querySelector(hash);
    if (!target) {
      return;
    }

    const headerOffset = getHeaderOffset() + 16;
    const top = window.scrollY + target.getBoundingClientRect().top - headerOffset;

    try {
      window.scrollTo({
        top,
        behavior: 'smooth'
      });
    } catch (error) {
      window.scrollTo(0, top);
    }

    if (shouldFocus) {
      window.setTimeout(() => {
        const previousTabindex = target.getAttribute('tabindex');
        if (!target.hasAttribute('tabindex')) {
          target.setAttribute('tabindex', '-1');
        }
        target.focus({ preventScroll: true });
        if (previousTabindex === null) {
          target.addEventListener('blur', () => {
            target.removeAttribute('tabindex');
          }, { once: true });
        }
      }, 320);
    }
  };

  const handleDocumentClick = (event) => {
    const link = event.target.closest('a[href^="#"]');
    if (!link) {
      return;
    }

    const href = link.getAttribute('href');
    if (!href || href === '#') {
      return;
    }

    const target = document.querySelector(href);
    if (!target) {
      return;
    }

    event.preventDefault();
    if (window.history && typeof window.history.pushState === 'function') {
      window.history.pushState(null, '', href);
    }

    smoothScrollToHash(href, true);

    if (dom.navMenu && dom.navMenu.contains(link)) {
      setMenuOpen(false);
    }
  };

  const bindEvents = () => {
    if (dom.navToggle) {
      dom.navToggle.addEventListener('click', () => {
        setMenuOpen(!state.isMenuOpen);
      });
    }

    if (dom.pricingToggle) {
      dom.pricingToggle.addEventListener('click', handlePricingToggle);
    }

    if (dom.faqMount) {
      dom.faqMount.addEventListener('click', handleFaqToggle);
    }

    document.addEventListener('click', handleDocumentClick);

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && state.isMenuOpen) {
        setMenuOpen(false);
        if (dom.navToggle) {
          dom.navToggle.focus();
        }
      }
    });

    document.addEventListener('click', (event) => {
      if (!state.isMenuOpen || !dom.navMenu || !dom.navToggle) {
        return;
      }

      const clickedInsideMenu = dom.navMenu.contains(event.target);
      const clickedToggle = dom.navToggle.contains(event.target);
      if (!clickedInsideMenu && !clickedToggle) {
        setMenuOpen(false);
      }
    });
  };

  const init = () => {
    cacheDom();
    renderNavigation();
    renderHero();
    renderFeatures();
    renderPricing();
    renderFaq();
    renderFinalCta();
    renderFooter();
    bindEvents();
    setMenuOpen(false);
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init, { once: true });
  } else {
    init();
  }
})();

