  /**
   * Renders navigation content from config.
   *
   * @returns {void}
   */
  function renderNavigation() {
    const navigation = APP_CONFIG.navigation;

    setText(dom.navBrand, navigation.brandLabel);
    setAttribute(dom.navToggle, 'aria-label', navigation.toggleOpenLabel);

    if (dom.navLinksList) {
      const navLinks = Array.isArray(navigation.links) ? navigation.links : [];
      dom.navLinksList.innerHTML = navLinks.map(function renderLink(link) {
        return '<li><a href="' + escapeHtml(link.href || '#') + '">' + escapeHtml(link.label || '') + '</a></li>';
      }).join('');
    }

    if (dom.navActions) {
      setHtml(dom.navActions, createButtonLinkMarkup('button-primary', navigation.cta));
    }
  }

