    const features = APP_CONFIG.features;

    setText(dom.featuresEyebrow, features.eyebrow);
    setText(dom.featuresTitle, features.title);
    setText(dom.featuresDescription, features.description);

    if (!dom.featuresMount) {
      return;
    }

    const items = Array.isArray(features.items) ? features.items : [];
    dom.featuresMount.innerHTML = items.map(function renderFeature(item) {
      return [
        '<article class="feature-card">',
        '  <h3>' + escapeHtml(item.title || '') + '</h3>',
        '  <p>' + escapeHtml(item.description || '') + '</p>',
        '</article>'
      ].join('');
    }).join('');
  }

  /**
   * Creates pricing plan card markup.
   *
   * @param {object} plan Pricing plan.
   * @param {'monthly'|'yearly'} billingPeriod Active billing period.
   * @returns {string} Pricing card markup.
   */
  function createPricingCardMarkup(plan, billingPeriod) {
    const display = getPricingDisplay(plan, billingPeriod);
    const planFeatures = Array.isArray(plan.features) ? plan.features : [];
    const recommendedMarkup = plan.recommended
      ? '<p class="pricing-badge" aria-label="推荐方案">' + escapeHtml(APP_CONFIG.pricing.recommendedBadge) + '</p>'
      : '';
    const fallbackClass = display.isFallback ? ' is-fallback' : '';

    return [
      '<article class="pricing-card' + (plan.recommended ? ' is-recommended' : '') + '"' + (plan.recommended ? ' data-recommended="true"' : '') + '>',
      recommendedMarkup,
      '<h3>' + escapeHtml(plan.name || '') + '</h3>',
      '<p>' + escapeHtml(plan.description || '') + '</p>',
      '<div class="pricing-value' + fallbackClass + '">',
      '  <span class="pricing-amount" data-role="price-value">' + escapeHtml(display.value) + '</span>',
      '  <span class="pricing-period" data-role="price-period">' + escapeHtml(display.period) + '</span>',
      '</div>',
      '<ul class="pricing-features">',
      planFeatures.map(function renderFeature(feature) {
        return '<li>' + escapeHtml(feature) + '</li>';
      }).join(''),
      '</ul>',
      createButtonLinkMarkup('button-secondary', plan.cta),
      '</article>'
    ].join('');
  }

  /**
   * Renders the pricing section and toggle labels.
   *
   * @returns {void}
   */
  function renderPricing() {
    const pricing = APP_CONFIG.pricing;

    setText(dom.pricingEyebrow, pricing.eyebrow);
    setText(dom.pricingTitle, pricing.title);
    setText(dom.pricingDescription, pricing.description);

    if (dom.pricingToggleButtons && dom.pricingToggleButtons.length >= 2) {
      const monthlyButton = dom.pricingToggleButtons[0];
      const yearlyButton = dom.pricingToggleButtons[1];
      setText(monthlyButton, pricing.toggleLabels.monthly);
      setText(yearlyButton, pricing.toggleLabels.yearly);
    }

    renderPricingCards();
    syncPricingToggleState();
  }

  /**
   * Re-renders pricing cards for the current billing period.
   *
   * @returns {void}
   */
  function renderPricingCards() {
    if (!dom.pricingMount) {
      return;
    }

    const plans = getSafePlans();
    dom.pricingMount.innerHTML = plans.map(function renderPlan(plan) {
      return createPricingCardMarkup(plan, state.billingPeriod);
    }).join('');
  }

  /**
   * Syncs pricing toggle button visual and aria states.
   *
   * @returns {void}
   */
  function syncPricingToggleState() {
    if (!dom.pricingToggleButtons || dom.pricingToggleButtons.length < 2) {
      return;
    }

    const isMonthly = state.billingPeriod === 'monthly';
    const monthlyButton = dom.pricingToggleButtons[0];
    const yearlyButton = dom.pricingToggleButtons[1];

    monthlyButton.classList.toggle('is-active', isMonthly);
    yearlyButton.classList.toggle('is-active', !isMonthly);
    monthlyButton.setAttribute('aria-pressed', isMonthly ? 'true' : 'false');
    yearlyButton.setAttribute('aria-pressed', isMonthly ? 'false' : 'true');
  }

