      const footerLinks = Array.isArray(APP_CONFIG.footer.links) ? APP_CONFIG.footer.links : [];
      dom.footerLinks.innerHTML = footerLinks.map(function renderFooterLink(link) {
        const aria = link.ariaLabel ? ' aria-label="' + escapeHtml(link.ariaLabel) + '"' : '';
